 66	/**
 67	 * @author Vitaliy Fedoriv
 68	 */
 69	
 70	@RestController
 71	@CrossOrigin(exposedHeaders = "errors, content-type")
 72	@RequestMapping("/api")
 73	public class OwnerRestControllerV1 implements OwnersApi {
 74	
 75	    /** Maximum number of owners a single city may contain; creating another owner there is rejected. */
 76	    static final int CITY_CAPACITY = 50;
 77	
 78	    /** Owners already in a city at or above which (and below {@link #CITY_CAPACITY}) a new owner there gets 'capacityWarning'. */
 79	    static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
 80	
 81	    /** Maximum number of owners that may be created per (business-day adjusted) registration date; further creates are rejected. */
 82	    static final int DAILY_OWNER_LIMIT = 100;
 83	
 84	    /** Owners already created on the same registration date beyond which a new owner gets 'bulkSignupWarning'. */
 85	    static final int BULK_SIGNUP_THRESHOLD = 80;
 86	
 87	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
 88	
 89	    private final ClinicService clinicService;
 90	
 91	    private final OwnerMapper ownerMapper;
 92	
 93	    private final PetMapper petMapper;
 94	
 95	    private final VisitMapper visitMapper;
 96	
 97	    private final AuditEventPublisher auditEventPublisher;
 98	
 99	    private final WelcomeNotifier welcomeNotifier;
100	
101	    public OwnerRestControllerV1(ClinicService clinicService,
102	                                 OwnerMapper ownerMapper,
103	                                 PetMapper petMapper,
104	                                 VisitMapper visitMapper,
105	                                 AuditEventPublisher auditEventPublisher,
106	                                 WelcomeNotifier welcomeNotifier) {
107	        this.clinicService = clinicService;
108	        this.ownerMapper = ownerMapper;
109	        this.petMapper = petMapper;
110	        this.visitMapper = visitMapper;
111	        this.auditEventPublisher = auditEventPublisher;
112	        this.welcomeNotifier = welcomeNotifier;
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
118	        Collection<Owner> owners;
119	        if (lastName != null) {
120	            owners = this.clinicService.findOwnerByLastName(lastName);
121	        } else {
122	            owners = this.clinicService.findAllOwners();
123	        }
124	        if (owners.isEmpty()) {
125	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
126	        }
127	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
133	        Owner owner = this.clinicService.findOwnerById(ownerId);
134	        if (owner == null) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Transactional
142	    @Override
143	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
144	        // A repeated create with an already-seen key returns the originally created owner.
145	        if (idempotencyKey != null) {
146	            Owner existing = this.clinicService.findOwnerByIdempotencyKey(idempotencyKey);
147	            if (existing != null) {
148	                return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), ownerLocation(existing), HttpStatus.OK);
149	            }
150	        }
151	        List<String> missingFields = RequiredOwnerFields.missingFields(ownerFieldsDto);
152	        if (!missingFields.isEmpty()) {
153	            throw new MissingRequiredFieldsException(missingFields);
154	        }
155	        OwnerPostcode.validate(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
156	        OwnerEmail.validate(ownerFieldsDto.getEmail());
157	        OwnerRegistrationDate.validate(ownerFieldsDto.getRegistrationDate());
158	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
159	        owner.setTelephone(OwnerTelephone.normalize(ownerFieldsDto.getTelephone()));
160	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
161	        applyAddress(owner, ownerFieldsDto);
162	        // Duplicate detection uses the identity key alone (telephone, email, soundex of the last name).
163	        owner.setHouseholdId(this.clinicService.householdIdOf(owner));
164	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
165	        if (this.clinicService.ownerIdentityKeyExists(owner)) {
166	            throw new DuplicateIdentityException(owner.getIdentityKey());
167	        }
168	        long ownersInCity = this.clinicService.countOwnersInCity(ownerFieldsDto.getCity());
169	        if (ownersInCity >= CITY_CAPACITY) {
170	            throw new CityCapacityExceededException(ownerFieldsDto.getCity(), CITY_CAPACITY);
171	        }
172	        owner.setCapacityWarning(ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD);
173	        LocalDate registrationDate = BusinessDays.rollForward(
174	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
175	        long ownersCreatedToday = this.clinicService.countOwnersRegisteredOn(registrationDate);
176	        if (ownersCreatedToday >= DAILY_OWNER_LIMIT) {
177	            throw new DailyOwnerLimitExceededException(DAILY_OWNER_LIMIT);
178	        }
179	        owner.setRegistrationDate(registrationDate);
180	        owner.setBulkSignupWarning(ownersCreatedToday > BULK_SIGNUP_THRESHOLD);
181	        // A declared household member is not a suspected duplicate.
182	        owner.setPossibleDuplicateOf(declaredHouseholdMember ? null : this.clinicService.findPossibleDuplicateOf(owner));
183	        owner.setIdempotencyKey(idempotencyKey);
184	        // The level cannot exceed one above the highest level among the existing household members.
185	        OptionalInt maxHouseholdLevel = this.clinicService.findHouseholdMembers(owner).stream()
186	            .mapToInt(ownerMapper::toMembershipLevel)
187	            .max();
188	        owner.setMembershipLevelCap(maxHouseholdLevel.isPresent() ? maxHouseholdLevel.getAsInt() + 1 : null);
189	        this.clinicService.saveOwner(owner);
190	        AUDIT.info("Owner created: id={}, memberId={}, region={}, fiscalYear={}, "
191	                + "registrationDate={}, membershipPoints={}, membershipLevel={}",
192	            owner.getId(), owner.getMemberId(), ownerMapper.toLocality(owner), ownerMapper.toFiscalYear(owner),
193	            owner.getRegistrationDate(), ownerMapper.toMembershipPoints(owner), ownerMapper.toMembershipLevel(owner));
194	        OwnerCreatedEvent created = this.auditEventPublisher.ownerCreated(owner, ownerMapper.toMembershipLevel(owner));
195	        this.welcomeNotifier.welcome(created);
196	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), ownerLocation(owner), HttpStatus.CREATED);
197	    }
198	
199	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
200	    @Override
201	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
202	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
203	        if (currentOwner == null) {
204	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
205	        }
206	        String telephone = OwnerTelephone.normalize(ownerFieldsDto.getTelephone());
207	        OwnerPostcode.validate(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
208	        OwnerEmail.validate(ownerFieldsDto.getEmail());
209	        OwnerRegistrationDate.validate(ownerFieldsDto.getRegistrationDate());
210	        applyAddress(currentOwner, ownerFieldsDto);
211	        currentOwner.setCity(ownerFieldsDto.getCity());
212	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
213	        currentOwner.setLastName(ownerFieldsDto.getLastName());
214	        currentOwner.setTelephone(telephone);
215	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
216	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
217	        if (ownerFieldsDto.getRegistrationDate() != null) {
218	            currentOwner.setRegistrationDate(BusinessDays.rollForward(ownerFieldsDto.getRegistrationDate()));
219	        }
220	        if (ownerFieldsDto.getBirthDate() != null) {
221	            currentOwner.setBirthDate(ownerFieldsDto.getBirthDate());
222	        }
223	        currentOwner.setTitle(ownerFieldsDto.getTitle() == null ? null : ownerFieldsDto.getTitle().getValue());
224	        this.clinicService.saveOwner(currentOwner);
225	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
226	    }
227	
228	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
229	    @Transactional
230	    @Override
231	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
232	        Owner owner = this.clinicService.findOwnerById(ownerId);
233	        if (owner == null) {
234	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
235	        }
236	        this.clinicService.deleteOwner(owner);
237	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
238	    }
239	
240	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
241	    @Override
242	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
243	        Owner owner = this.clinicService.findOwnerById(ownerId);
244	        if (owner == null) {
245	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
246	        }
247	        HttpHeaders headers = new HttpHeaders();
248	        Pet pet = petMapper.toPet(petFieldsDto);
249	        owner.setId(ownerId);
250	        pet.setOwner(owner);
251	        pet.getType().setName(null);
252	        this.clinicService.savePet(pet);
253	        PetDto petDto = petMapper.toPetDto(pet);
254	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
255	            .buildAndExpand(pet.getId()).toUri());
256	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
257	    }
258	
259	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
260	    @Override
261	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
262	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
263	        if (currentOwner != null) {
264	            Pet currentPet = this.clinicService.findPetById(petId);
265	            if (currentPet != null) {
266	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
267	                currentPet.setName(petFieldsDto.getName());
268	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
269	                this.clinicService.savePet(currentPet);
270	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
271	            }
272	        }
273	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
274	    }
275	
276	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
277	    @Override
278	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
279	        HttpHeaders headers = new HttpHeaders();
280	        Visit visit = visitMapper.toVisit(visitFieldsDto);
281	        Pet pet = new Pet();
282	        pet.setId(petId);
283	        visit.setPet(pet);
284	        this.clinicService.saveVisit(visit);
285	        VisitDto visitDto = visitMapper.toVisitDto(visit);
286	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
287	            .buildAndExpand(visit.getId()).toUri());
288	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
289	    }
290	
291	
292	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
293	    @Override
294	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
295	        Owner owner = this.clinicService.findOwnerById(ownerId);
296	        if (owner != null) {
297	            Pet pet = owner.getPet(petId);
298	            if (pet != null) {
299	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
300	            }
301	        }
302	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
303	    }
304	
305	    /**
306	     * Stores the normalized structured address lines (absent when not supplied) and the composed
307	     * 'address': the structured lines when 'addressLine1' is present, otherwise the flat address.
308	     */
309	    private static void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
310	        owner.setAddressLine1(AddressNormalizer.normalizeOptional(ownerFieldsDto.getAddressLine1()));
311	        owner.setAddressLine2(owner.getAddressLine1() == null ? null
312	            : AddressNormalizer.normalizeOptional(ownerFieldsDto.getAddressLine2()));
313	        owner.setAddress(AddressNormalizer.compose(
314	            ownerFieldsDto.getAddressLine1(), ownerFieldsDto.getAddressLine2(), ownerFieldsDto.getAddress()));
315	    }
316	
317	    private static HttpHeaders ownerLocation(Owner owner) {
318	        HttpHeaders headers = new HttpHeaders();
319	        headers.setLocation(UriComponentsBuilder.newInstance()
320	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
321	        return headers;
322	    }
323	
324	    private static String normalizeEmail(String email) {
325	        return email == null ? null : email.toLowerCase(Locale.ROOT);
326	    }
327	}
