148	                return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), ownerLocation(existing), HttpStatus.OK);
149	            }
150	        }
151	        List<String> missingFields = RequiredOwnerFields.missingFields(ownerFieldsDto);
152	        if (!missingFields.isEmpty()) {
153	            throw new MissingRequiredFieldsException(missingFields);
154	        }
155	        OwnerPostcode.validate(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
156	        OwnerEmail.validate(ownerFieldsDto.getEmail());
157	        OwnerRegistrationDate.validate(ownerFieldsDto.getRegistrationDate());
158	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
159	        owner.setTelephone(OwnerTelephone.normalize(ownerFieldsDto.getTelephone()));
160	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
161	        applyAddress(owner, ownerFieldsDto);
162	        // Duplicate detection uses the identity key alone (telephone, email, soundex of the last name).
163	        owner.setHouseholdId(this.clinicService.householdIdOf(owner));
164	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
165	        if (this.clinicService.ownerIdentityKeyExists(owner)) {
166	            throw new DuplicateIdentityException(owner.getIdentityKey());
167	        }
168	        long ownersInCity = this.clinicService.countOwnersInCity(ownerFieldsDto.getCity());
169	        if (ownersInCity >= CITY_CAPACITY) {
170	            throw new CityCapacityExceededException(ownerFieldsDto.getCity(), CITY_CAPACITY);
171	        }
172	        owner.setCapacityWarning(ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD);
173	        LocalDate registrationDate = BusinessDays.rollForward(
174	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
175	        long ownersCreatedToday = this.clinicService.countOwnersRegisteredOn(registrationDate);
176	        if (ownersCreatedToday >= DAILY_OWNER_LIMIT) {
177	            throw new DailyOwnerLimitExceededException(DAILY_OWNER_LIMIT);
178	        }
179	        owner.setRegistrationDate(registrationDate);
180	        owner.setBulkSignupWarning(ownersCreatedToday > BULK_SIGNUP_THRESHOLD);
181	        // A declared household member is not a suspected duplicate.
182	        owner.setPossibleDuplicateOf(declaredHouseholdMember ? null : this.clinicService.findPossibleDuplicateOf(owner));
183	        owner.setIdempotencyKey(idempotencyKey);
184	        // The level cannot exceed one above the highest level among the existing household members.
185	        OptionalInt maxHouseholdLevel = this.clinicService.findHouseholdMembers(owner).stream()
186	            .mapToInt(ownerMapper::toMembershipLevel)
187	            .max();
188	        owner.setMembershipLevelCap(maxHouseholdLevel.isPresent() ? maxHouseholdLevel.getAsInt() + 1 : null);
189	        this.clinicService.saveOwner(owner);
190	        AUDIT.info("Owner created: id={}, memberId={}, region={}, fiscalYear={}, "
191	                + "registrationDate={}, membershipPoints={}, membershipLevel={}",
192	            owner.getId(), owner.getMemberId(), ownerMapper.toLocality(owner), ownerMapper.toFiscalYear(owner),
193	            owner.getRegistrationDate(), ownerMapper.toMembershipPoints(owner), ownerMapper.toMembershipLevel(owner));
194	        OwnerCreatedEvent created = this.auditEventPublisher.ownerCreated(owner, ownerMapper.toMembershipLevel(owner));
195	        this.welcomeNotifier.welcome(created);
196	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), ownerLocation(owner), HttpStatus.CREATED);
197	    }
