    36	        if (domain.endsWith(".")) {
    37	            domain = domain.substring(0, domain.length() - 1);
    38	        }
    39	        for (String blocked : DISPOSABLE_DOMAINS) {
    40	            if (domain.equals(blocked) || domain.endsWith("." + blocked)) {
