    11	public final class OwnerPostcode {
    12	
    13	    private static final Pattern FOUR_DIGITS = Pattern.compile("^[0-9]{4}$");
    14	
    15	    /** Inclusive postcode range per region, keyed by the regions of {@link OwnerMapper#CITY_REGIONS}. */
    16	    public static final Map<String, int[]> RANGES_BY_REGION = Map.of(
    17	        "NSW", new int[] {2000, 2099},
    18	        "VIC", new int[] {3000, 3099},
    19	        "QLD", new int[] {4000, 4099});
    20	
    21	    /** The region of owners whose postcode and city match no known region. */
    22	    public static final String UNKNOWN_REGION = "UNKNOWN";
    23	
    24	    private OwnerPostcode() {
    25	    }
    26	
    27	    /**
    28	     * The owner's region: the region whose range contains the postcode; when the postcode is absent or
    29	     * in no known range, the region of the city from {@link OwnerMapper#CITY_REGIONS}, or
    30	     * {@value #UNKNOWN_REGION} when the city is not listed.
    31	     *
    32	     * @param postcode the postcode, may be {@code null}
    33	     * @param city the city, may be {@code null}
    34	     * @return the region, never {@code null}
    35	     */
    36	    public static String regionOf(String postcode, String city) {
    37	        String postcodeRegion = regionOf(postcode);
    38	        if (postcodeRegion != null) {
    39	            return postcodeRegion;
    40	        }
    41	        return city == null ? UNKNOWN_REGION : OwnerMapper.CITY_REGIONS.getOrDefault(city, UNKNOWN_REGION);
    42	    }
    43	
    44	    /**
    45	     * The region whose range in {@link #RANGES_BY_REGION} contains the postcode.
    46	     *
    47	     * @param postcode the postcode, may be {@code null}
    48	     * @return the region, or {@code null} when the postcode is absent, not 4 digits or in no known range
    49	     */
    50	    public static String regionOf(String postcode) {
    51	        if (postcode == null || !FOUR_DIGITS.matcher(postcode).matches()) {
    52	            return null;
    53	        }
    54	        int value = Integer.parseInt(postcode);
    55	        for (Map.Entry<String, int[]> entry : RANGES_BY_REGION.entrySet()) {
    56	            if (value >= entry.getValue()[0] && value <= entry.getValue()[1]) {
    57	                return entry.getKey();
    58	            }
    59	        }
    60	        return null;
    61	    }
    62	
    63	    /**
    64	     * Checks a postcode for the given city. An absent postcode is accepted; a present one must be
    65	     * 4 digits and, when the city has a known region, lie within that region's range.
    66	     *
    67	     * @param postcode the postcode as supplied in the request, may be {@code null}
    68	     * @param city the owner's city
    69	     * @throws InvalidPostcodeException if the postcode is malformed or out of range for the city's region
    70	     */
    71	    public static void validate(String postcode, String city) {
    72	        if (postcode == null) {
    73	            return;
    74	        }
    75	        if (!FOUR_DIGITS.matcher(postcode).matches()) {
    76	            throw new InvalidPostcodeException(postcode, "Postcode must be 4 digits");
    77	        }
    78	        String region = city == null ? null : OwnerMapper.CITY_REGIONS.get(city);
    79	        int[] range = region == null ? null : RANGES_BY_REGION.get(region);
    80	        if (range == null) {
    81	            return;
    82	        }
    83	        int value = Integer.parseInt(postcode);
    84	        if (value < range[0] || value > range[1]) {
    85	            throw new InvalidPostcodeException(postcode, "Postcode for " + city + " (" + region
    86	                + ") must be between " + range[0] + " and " + range[1]);
    87	        }
    88	    }
